/*
 * D3UT — common confusions (FAQ).
 * Each entry: { id, q: [en, id], a: [en, id], ex?: [[german, [en, id]], ...], topics?: [topic ids] }
 */
window.C3KO_FAQ = [
  { id: "gender", q: ["Der, die or das?", "Der, die atau das?"],
    a: ["Gender often can't be guessed from meaning, so learn each noun with its article. Some endings help: -ung, -heit, -keit, -schaft, -ion, -tät are feminine (die); -chen, -lein, -ment, -um are neuter (das); days, months, seasons and -ling, -ismus are masculine (der). In compounds the last part decides.", "Gender sering tidak bisa ditebak dari artinya, jadi hafalkan setiap kata benda bersama artikelnya. Beberapa akhiran membantu: -ung, -heit, -keit, -schaft, -ion, -tät feminin (die); -chen, -lein, -ment, -um netral (das); hari, bulan, musim dan -ling, -ismus maskulin (der). Dalam kata majemuk bagian terakhir yang menentukan."],
    ex: [["{die} Zeitung, {die} Freiheit", ["-ung, -heit → die", "-ung, -heit → die"]], ["{das} Mädchen", ["-chen → das (even for a girl)", "-chen → das (meskipun anak perempuan)"]], ["{der} Montag, {der} Winter", ["days, seasons → der", "hari, musim → der"]], ["die Haus{tür}", ["compound: die Tür decides", "majemuk: die Tür menentukan"]]],
    topics: ["a1-gender"] },
  { id: "nicht-kein", q: ["Nicht or kein?", "Nicht atau kein?"],
    a: ["Kein negates a noun that would have ein or no article (ein Auto → kein Auto; Zeit → keine Zeit). Nicht negates everything else: verbs, adjectives, adverbs, names and nouns with der/die/das or a possessive.", "Kein menegasikan kata benda yang seharusnya memakai ein atau tanpa artikel (ein Auto → kein Auto; Zeit → keine Zeit). Nicht menegasikan selain itu: kata kerja, kata sifat, kata keterangan, nama, dan kata benda dengan der/die/das atau kata kepemilikan."],
    ex: [["Ich habe {kein} Auto.", ["ein Auto → kein", "ein Auto → kein"]], ["Ich habe {keine} Zeit.", ["no article → kein", "tanpa artikel → kein"]], ["Das ist {nicht} mein Auto.", ["possessive → nicht", "kepemilikan → nicht"]], ["Ich komme {nicht}.", ["verb → nicht", "kata kerja → nicht"]]],
    topics: ["a1-negation"] },
  { id: "akk-dat", q: ["Accusative or dative?", "Akusatif atau datif?"],
    a: ["The accusative is the direct object (what or whom you see, have, buy). The dative is the receiver or beneficiary (to whom / for whom), the object of dative verbs (helfen, danken, gefallen, gehören), and comes after dative prepositions (aus, bei, mit, nach, seit, von, zu). Two-way prepositions depend on wo? / wohin?.", "Akusatif adalah objek langsung (apa atau siapa yang dilihat, dimiliki, dibeli). Datif adalah penerima atau yang mendapat manfaat (kepada / untuk siapa), objek kata kerja datif (helfen, danken, gefallen, gehören), dan setelah kata depan datif (aus, bei, mit, nach, seit, von, zu). Kata depan dua arah tergantung wo? / wohin?."],
    ex: [["Ich sehe {den} Mann.", ["direct object → accusative", "objek langsung → akusatif"]], ["Ich gebe {dem} Mann das Buch.", ["receiver → dative", "penerima → datif"]], ["Ich helfe {dem} Mann.", ["helfen → dative", "helfen → datif"]], ["Ich fahre mit {dem} Bus.", ["mit → dative", "mit → datif"]]],
    topics: ["a1-accusative", "a2-dative", "a2-dative-verbs", "a2-prepositions"] },
  { id: "wo-wohin", q: ["In dem or in den? (wo / wohin)", "In dem atau in den? (wo / wohin)"],
    a: ["The nine two-way prepositions (an, auf, hinter, in, neben, über, unter, vor, zwischen) take the dative for location (wo?) and the accusative for movement to a place (wohin?). Contractions: im / am (dative), ins / ans (accusative).", "Sembilan kata depan dua arah (an, auf, hinter, in, neben, über, unter, vor, zwischen) diikuti datif untuk lokasi (wo?) dan akusatif untuk gerakan menuju tempat (wohin?). Penggabungan: im / am (datif), ins / ans (akusatif)."],
    ex: [["Ich bin {im} Kino.", ["wo? → dative", "wo? → datif"]], ["Ich gehe {ins} Kino.", ["wohin? → accusative", "wohin? → akusatif"]], ["Das Buch liegt auf {dem} Tisch. / Ich lege es auf {den} Tisch.", ["position / movement", "posisi / gerakan"]]],
    topics: ["a2-two-way", "a2-wo-wohin"] },
  { id: "haben-sein", q: ["Perfekt with haben or sein?", "Perfekt dengan haben atau sein?"],
    a: ["Most verbs take haben. Sein is used for verbs of movement from A to B (gehen, fahren, fliegen, kommen), changes of state (aufstehen, einschlafen, sterben, werden) and for sein, bleiben and passieren. These verbs have no direct object.", "Kebanyakan kata kerja memakai haben. Sein dipakai untuk kata kerja gerakan dari A ke B (gehen, fahren, fliegen, kommen), perubahan keadaan (aufstehen, einschlafen, sterben, werden) dan untuk sein, bleiben serta passieren. Kata kerja ini tidak punya objek langsung."],
    ex: [["Ich {bin} nach Berlin gefahren.", ["movement → sein", "gerakan → sein"]], ["Ich {habe} viel gearbeitet.", ["no movement → haben", "tanpa gerakan → haben"]], ["Er {ist} zu Hause geblieben.", ["bleiben → sein", "bleiben → sein"]]],
    topics: ["a2-perfekt-haben", "a2-perfekt-sein"] },
  { id: "als-wenn", q: ["Als, wenn or wann?", "Als, wenn atau wann?"],
    a: ["Als: a single event or period in the past (als ich Kind war). Wenn: repeated events (whenever), present or future events, and conditions (if). Wann: question word 'when?', also inside indirect questions.", "Als: satu peristiwa atau periode di masa lalu (als ich Kind war). Wenn: peristiwa berulang (setiap kali), peristiwa kini atau masa depan, dan syarat (jika). Wann: kata tanya 'kapan?', juga dalam pertanyaan tidak langsung."],
    ex: [["{Als} ich 18 war, zog ich nach Wien.", ["once in the past", "sekali di masa lalu"]], ["{Wenn} ich Zeit habe, lese ich.", ["whenever / if", "setiap kali / jika"]], ["{Wann} kommst du?", ["question", "pertanyaan"]]],
    topics: ["b1-als-wenn"] },
  { id: "weil-denn", q: ["Weil or denn?", "Weil atau denn?"],
    a: ["Both mean 'because'. After weil the verb goes to the end of the clause. Denn joins two main clauses, so the word order stays normal. Deshalb ('that's why') gives the result and takes position 1 (verb right after it).", "Keduanya berarti 'karena'. Setelah weil kata kerja di akhir klausa. Denn menggabungkan dua induk kalimat, jadi susunannya tetap biasa. Deshalb ('karena itu') menyatakan akibat dan menempati posisi 1 (kata kerja langsung menyusul)."],
    ex: [["Ich bleibe hier, {weil} ich krank {bin}.", ["weil → verb last", "weil → kata kerja di akhir"]], ["Ich bleibe hier, {denn} ich {bin} krank.", ["denn → normal order", "denn → susunan biasa"]], ["Ich bin krank, {deshalb bleibe} ich hier.", ["deshalb → verb next", "deshalb → kata kerja menyusul"]]],
    topics: ["a2-subordinate", "a2-conjunctions"] },
  { id: "du-sie", q: ["Du or Sie?", "Du atau Sie?"],
    a: ["Du (and ihr for several people) is for friends, family, children and often colleagues of your age; young people usually say du to each other. Sie (always with a capital S, singular and plural) is for adults you don't know, in shops, offices and formal situations. The verb after Sie is the same as for sie (they).", "Du (dan ihr untuk beberapa orang) untuk teman, keluarga, anak-anak dan sering rekan kerja sebaya; anak muda biasanya saling memakai du. Sie (selalu S kapital, tunggal dan jamak) untuk orang dewasa yang tidak dikenal, di toko, kantor dan situasi resmi. Kata kerja setelah Sie sama dengan sie (mereka)."],
    ex: [["Wie heißt {du}?", ["informal", "informal"]], ["Wie heißen {Sie}?", ["polite", "sopan"]], ["Kommt {ihr} mit?", ["informal plural", "informal jamak"]]],
    topics: ["a1-pronouns"] },
  { id: "seit-vor", q: ["Seit, vor or für (time)?", "Seit, vor atau für (waktu)?"],
    a: ["Seit + dative + present: something started in the past and is still true (Ich wohne seit 2020 hier). Vor + dative: ago (vor zwei Jahren). Für: a planned duration (für zwei Wochen). For a finished duration in the past, just use the accusative of time (Ich habe zwei Jahre dort gewohnt).", "Seit + datif + kala kini: sesuatu dimulai di masa lalu dan masih berlaku (Ich wohne seit 2020 hier). Vor + datif: yang lalu (vor zwei Jahren). Für: durasi yang direncanakan (für zwei Wochen). Untuk durasi yang sudah selesai, cukup akusatif waktu (Ich habe zwei Jahre dort gewohnt)."],
    ex: [["Ich lerne {seit} einem Jahr Deutsch.", ["still learning", "masih belajar"]], ["Ich bin {vor} einem Jahr gekommen.", ["ago", "yang lalu"]], ["Ich fahre {für} eine Woche nach Rom.", ["planned duration", "durasi rencana"]]],
    topics: ["a2-prepositions"] },
  { id: "legen-liegen", q: ["Legen or liegen? Stellen or stehen?", "Legen atau liegen? Stellen atau stehen?"],
    a: ["Legen, stellen, setzen, hängen (weak, + accusative) mean putting something somewhere: an action, wohin?. Liegen, stehen, sitzen, hängen (strong, + dative) describe where something is: a position, wo?. Flat things lie, upright things stand.", "Legen, stellen, setzen, hängen (lemah, + akusatif) berarti menaruh sesuatu: tindakan, wohin?. Liegen, stehen, sitzen, hängen (kuat, + datif) menggambarkan letak sesuatu: posisi, wo?. Benda datar berbaring, benda tegak berdiri."],
    ex: [["Ich {lege} das Handy auf den Tisch.", ["action → accusative", "tindakan → akusatif"]], ["Das Handy {liegt} auf dem Tisch.", ["position → dative", "posisi → datif"]], ["Die Flasche {steht} im Kühlschrank.", ["upright → stehen", "tegak → stehen"]]],
    topics: ["a2-wo-wohin", "a2-two-way"] },
  { id: "kennen-wissen", q: ["Kennen or wissen?", "Kennen atau wissen?"],
    a: ["Kennen = be familiar with a person, place or thing; always + a noun or pronoun. Wissen = know a fact; usually + a clause (dass, wo, ob…) or es / das / etwas. Wissen is irregular: ich weiß, du weißt, er weiß.", "Kennen = mengenal orang, tempat atau benda; selalu + kata benda atau kata ganti. Wissen = tahu fakta; biasanya + klausa (dass, wo, ob…) atau es / das / etwas. Wissen tidak beraturan: ich weiß, du weißt, er weiß."],
    ex: [["Ich {kenne} Anna.", ["person → kennen", "orang → kennen"]], ["Ich {weiß}, wo sie wohnt.", ["fact → wissen", "fakta → wissen"]], ["{Kennst} du Hamburg?", ["place → kennen", "tempat → kennen"]]],
    topics: ["a1-present-stem"] },
  { id: "sie-ihr", q: ["sie, Sie or ihr?", "sie, Sie atau ihr?"],
    a: ["sie (small s) = she (with -t verb: sie kommt) or they (with -en verb: sie kommen). Sie (capital) = polite you (Sie kommen). ihr = you all (ihr kommt), or the dative 'to her' (ich helfe ihr), or the possessive 'her / their' (ihr Auto). Ihr with a capital = your (polite).", "sie (s kecil) = dia perempuan (dengan kata kerja -t: sie kommt) atau mereka (dengan -en: sie kommen). Sie (kapital) = Anda (Sie kommen). ihr = kalian (ihr kommt), atau datif 'kepadanya (perempuan)' (ich helfe ihr), atau kepemilikan 'miliknya / milik mereka' (ihr Auto). Ihr kapital = milik Anda."],
    ex: [["{sie} kommt / {sie} kommen", ["she / they", "dia / mereka"]], ["Kommen {Sie} mit?", ["polite you", "Anda"]], ["Ich helfe {ihr}. {Ihr} seid nett.", ["to her / you all", "kepadanya / kalian"]]],
    topics: ["a1-pronouns", "a2-pronoun-cases", "a1-possessives"] },
  { id: "aber-sondern", q: ["Aber or sondern?", "Aber atau sondern?"],
    a: ["Both translate 'but'. Sondern (but rather) comes after a negative statement and replaces it with the correct information. Aber (however) adds a contrast or limitation and doesn't cancel the first part.", "Keduanya berarti 'tetapi'. Sondern (melainkan) dipakai setelah pernyataan negatif dan menggantinya dengan informasi yang benar. Aber (namun) menambahkan kontras atau batasan tanpa membatalkan bagian pertama."],
    ex: [["Nicht rot, {sondern} blau.", ["correction", "koreksi"]], ["Es ist teuer, {aber} schön.", ["contrast", "kontras"]], ["Ich habe keine Zeit, {aber} ich komme.", ["contrast after negative", "kontras setelah negasi"]]],
    topics: ["a2-conjunctions", "b1-two-part-conj"] },
  { id: "will-werde", q: ["Ich will or ich werde?", "Ich will atau ich werde?"],
    a: ["Ich will (wollen) = I want. Ich werde (werden) = I will, or I'm becoming. Werden + infinitive is the future; werden + adjective or noun means become; werden + Partizip II is the passive.", "Ich will (wollen) = saya mau. Ich werde (werden) = saya akan, atau saya menjadi. Werden + infinitif adalah kala depan; werden + kata sifat atau kata benda berarti menjadi; werden + Partizip II adalah pasif."],
    ex: [["Ich {will} Arzt werden.", ["want", "mau"]], ["Ich {werde} dich anrufen.", ["future", "kala depan"]], ["Es {wird} kalt.", ["become", "menjadi"]], ["Das Haus {wird} gebaut.", ["passive", "pasif"]]],
    topics: ["b1-futur", "b1-passive", "a1-modals"] },
  { id: "adj-endings", q: ["Why gute, guten or guter?", "Mengapa gute, guten atau guter?"],
    a: ["Adjective endings depend on the article before them. After der/die/das: -e in the nominative singular (and accusative fem./neut.), -en everywhere else. After ein/kein/mein: the same, but -er (masc. nom.) and -es (neuter nom./acc.) where ein has no ending. With no article, the adjective takes the article's ending itself (kalter Kaffee, kaltes Wasser).", "Akhiran kata sifat tergantung artikel di depannya. Setelah der/die/das: -e pada nominatif tunggal (dan akusatif fem./netral), -en di tempat lain. Setelah ein/kein/mein: sama, tetapi -er (nom. mask.) dan -es (nom./akus. netral) di tempat ein tanpa akhiran. Tanpa artikel, kata sifat mengambil akhiran artikel itu sendiri (kalter Kaffee, kaltes Wasser)."],
    ex: [["der gut{e} Film / ein gut{er} Film", ["after der → -e; after ein → -er", "setelah der → -e; setelah ein → -er"]], ["das klein{e} Haus / ein klein{es} Haus", ["neuter", "netral"]], ["mit dem gut{en} Freund", ["dative → -en", "datif → -en"]]],
    topics: ["a2-adj-definite", "a2-adj-indefinite", "b1-adj-no-article"] },
  { id: "word-order", q: ["Where does the verb go?", "Di mana letak kata kerja?"],
    a: ["Main clause: the conjugated verb is always second (after one element, which can be the subject, a time, an object…). Infinitives, participles and separable prefixes go to the end. Subordinate clause (weil, dass, wenn, ob, obwohl, relative clauses): the conjugated verb goes to the very end. Yes/no questions and commands start with the verb.", "Induk kalimat: kata kerja terkonjugasi selalu kedua (setelah satu unsur, bisa subjek, waktu, objek…). Infinitif, partisip dan awalan terpisah di akhir. Anak kalimat (weil, dass, wenn, ob, obwohl, relatif): kata kerja terkonjugasi di paling akhir. Pertanyaan ya/tidak dan perintah dimulai dengan kata kerja."],
    ex: [["Morgen {fahre} ich nach Berlin.", ["verb second", "kata kerja kedua"]], ["Ich {habe} das Buch {gelesen}.", ["participle at the end", "partisip di akhir"]], ["…, weil ich müde {bin}.", ["subordinate: verb last", "anak kalimat: kata kerja terakhir"]]],
    topics: ["a1-word-order", "a2-subordinate", "a1-separable"] }
];
